import{_ as a,C as t,o as i,c as o,j as e,a as r,G as l,a3 as p}from"./chunks/framework.exbasbhr.js";const w=JSON.parse('{"title":"Repository Structure","description":"What each project in the solution does, and the components outside it","frontmatter":{"title":"Repository Structure","description":"What each project in the solution does, and the components outside it"},"headers":[],"relativePath":"en/dev/project-structure.md","filePath":"en/dev/project-structure.md"}'),c={name:"en/dev/project-structure.md"};function d(h,n,u,b,g,m){const s=t("ArticleMetadata");return i(),o("div",null,[n[0]||(n[0]=e("h1",{id:"repository-structure",tabindex:"-1"},[r("Repository Structure "),e("a",{class:"header-anchor",href:"#repository-structure","aria-label":'Permalink to "Repository Structure"'},"​")],-1)),l(s),n[1]||(n[1]=p(`<h2 id="projects-in-the-solution" tabindex="-1">Projects in the solution <a class="header-anchor" href="#projects-in-the-solution" aria-label="Permalink to &quot;Projects in the solution&quot;">​</a></h2><p><code>Ink Canvas.sln</code> contains 6 projects:</p><table tabindex="0"><thead><tr><th>Project</th><th>Purpose</th></tr></thead><tbody><tr><td><strong>InkCanvasForClass</strong></td><td>The main WPF application: windows, canvas, toolbar, settings, PowerPoint integration</td></tr><tr><td><strong>InkCanvas.PluginSdk</strong></td><td>Plugin SDK — the contract assembly third-party plugins compile against</td></tr><tr><td><strong>InkCanvas.Controls</strong></td><td>Reusable custom control library</td></tr><tr><td><strong>InkCanvas.IACoreHelper</strong></td><td>IACore handwriting recognition helper process</td></tr><tr><td><strong>InkCanvas.SettingsTreeView</strong></td><td>Tree navigation control used by the settings UI</td></tr><tr><td><strong>InkCanvas.PptAgent.Contracts</strong></td><td>Message contracts shared with the PowerPoint add-in</td></tr></tbody></table><h2 id="components-outside-the-solution" tabindex="-1">Components outside the solution <a class="header-anchor" href="#components-outside-the-solution" aria-label="Permalink to &quot;Components outside the solution&quot;">​</a></h2><p>Several directories are <strong>not part of the sln</strong> and must be built separately:</p><ul><li><strong>InkCanvas.PowerPointAddIn</strong> — the VSTO add-in installed into PowerPoint that pushes slide show events</li><li><strong>InkCanvas.NativeInk.Tests</strong> — tests for the native ink pipeline</li><li><strong>inkore-mcp</strong> — an MCP service written in Python, unrelated to the app build</li></ul><div class="tip custom-block"><p class="custom-block-title">Building only the app</p><p>Just open <code>Ink Canvas.sln</code>; none of the three directories above get pulled in.</p></div><h2 id="inside-the-main-application" tabindex="-1">Inside the main application <a class="header-anchor" href="#inside-the-main-application" aria-label="Permalink to &quot;Inside the main application&quot;">​</a></h2><p><code>Ink Canvas/</code> is organised by responsibility:</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Ink Canvas/</span></span>
<span class="line"><span>├── MainWindow_cs/     42 partial files of the main window</span></span>
<span class="line"><span>├── Ink/</span></span>
<span class="line"><span>│   └── Native/        Vortice-based low-latency ink pipeline</span></span>
<span class="line"><span>├── Automation/        Automation rule engine</span></span>
<span class="line"><span>├── IPC/               Pipe client for the PowerPoint add-in</span></span>
<span class="line"><span>├── Controls/          In-app controls</span></span>
<span class="line"><span>├── Helpers/           Assorted helper classes</span></span>
<span class="line"><span>├── Plugins/           Plugin host</span></span>
<span class="line"><span>├── Windows/           Standalone windows such as settings</span></span>
<span class="line"><span>├── Models/            Data models</span></span>
<span class="line"><span>├── MarkupExtensions/  XAML markup extensions</span></span>
<span class="line"><span>├── Resources/         Resources</span></span>
<span class="line"><span>└── libs/              External dependencies</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br></div></div><h3 id="about-the-42-mainwindow-partials" tabindex="-1">About the 42 MainWindow partials <a class="header-anchor" href="#about-the-42-mainwindow-partials" aria-label="Permalink to &quot;About the 42 MainWindow partials&quot;">​</a></h3><p>The main window carries a lot of logic, so it is split into 42 <code>partial class</code> files under <code>MainWindow_cs/</code>, grouped by feature (toolbar, page list, gestures, PowerPoint, and so on).</p><p>When changing main window logic:</p><ul><li>Find the partial that matches the feature; don&#39;t pile new code into the main file</li><li>Prefer a new partial file when adding a reasonably self-contained feature</li><li>Partials share fields — check whether other files use the same field before changing it</li></ul><h2 id="the-automation-rule-engine" tabindex="-1">The Automation rule engine <a class="header-anchor" href="#the-automation-rule-engine" aria-label="Permalink to &quot;The Automation rule engine&quot;">​</a></h2><p><code>Automation/</code> is a self-contained rule engine with a clear layout:</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Automation/</span></span>
<span class="line"><span>├── AutomationBootstrap.cs   Startup wiring</span></span>
<span class="line"><span>├── Abstractions/            Interface definitions</span></span>
<span class="line"><span>├── Triggers/                Triggers: when something fires</span></span>
<span class="line"><span>├── Rules/                   Rules: whether to act once fired</span></span>
<span class="line"><span>├── Actions/                 Action definitions</span></span>
<span class="line"><span>├── ActionHandlers/          Actual action execution</span></span>
<span class="line"><span>├── Services/                Supporting services</span></span>
<span class="line"><span>├── Models/  Enums/  Extensions/</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br></div></div><p>You extend it by adding new Trigger / Action / ActionHandler implementations and registering them in the bootstrap — not by editing existing branching logic.</p><h2 id="the-native-ink-pipeline" tabindex="-1">The native ink pipeline <a class="header-anchor" href="#the-native-ink-pipeline" aria-label="Permalink to &quot;The native ink pipeline&quot;">​</a></h2><p><code>Ink/Native/</code> is a low-latency wet-ink rendering path built on <strong>Vortice</strong> (.NET bindings for Direct3D/Direct2D). Together with the classic WPF <code>InkCanvas</code> it forms a <strong>dual rendering path</strong>:</p><ul><li><strong>Native path</strong>: ink currently being drawn renders straight on the GPU for lower latency</li><li><strong>Classic path</strong>: once a stroke is finished, the dry ink is handed to the WPF InkCanvas for compatibility with existing features</li></ul><p>Always verify both paths when touching this area; testing only one easily misses visual differences. <code>InkCanvas.NativeInk.Tests</code> exists specifically for this pipeline.</p><h2 id="cross-architecture-iacore-calls" tabindex="-1">Cross-architecture IACore calls <a class="header-anchor" href="#cross-architecture-iacore-calls" aria-label="Permalink to &quot;Cross-architecture IACore calls&quot;">​</a></h2><p>The IACore component used for handwriting recognition is <strong>32-bit only</strong>, while the main app usually runs as 64-bit. Recognition therefore lives in a separate <code>InkCanvas.IACoreHelper</code> process that the main app drives over inter-process communication.</p><p>Consequences:</p><ul><li>Recognition issues require looking at logs from <em>both</em> the app and the helper process</li><li>The app must tolerate the helper dying and restart it</li><li>To debug recognition, attach to the helper process, not the main one</li></ul><h2 id="the-three-way-powerpoint-relationship" tabindex="-1">The three-way PowerPoint relationship <a class="header-anchor" href="#the-three-way-powerpoint-relationship" aria-label="Permalink to &quot;The three-way PowerPoint relationship&quot;">​</a></h2><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>InkCanvasForClass (main app)</span></span>
<span class="line"><span>   │  IPC/PPTAgentPipeClient.cs (pipe client)</span></span>
<span class="line"><span>   │</span></span>
<span class="line"><span>   ├── InkCanvas.PptAgent.Contracts (message contracts shared by both sides)</span></span>
<span class="line"><span>   │</span></span>
<span class="line"><span>   └── InkCanvas.PowerPointAddIn (VSTO add-in, runs inside the PowerPoint process)</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br></div></div><p>When changing the protocol, <strong>update the contracts project together with both ends</strong>, otherwise one side will send messages the other cannot read. The add-in is outside the sln — remember to build and redeploy it into PowerPoint separately.</p>`,29))])}const k=a(c,[["render",d]]);export{w as __pageData,k as default};
